class Player {
    _money;
    _level;
    _carts;
    constructor() {
        this._carts = [];
        this._level = 0;
        this._money = 0;
    }
    addCart(cart) {
        this._carts.push(cart);
    }
    getCarts() {
        return this._carts;
    }
    getCartById(id) {
        return this._carts[id];
    }
    setMoney(money) {
        this._money = money;
    }
    money() {
        return this._money;
    }
    level() {
        return this._level;
    }
}
export default Player;
